INSERT INTO "Quiz" (id,"chapterId",title,description,"passingScore","createdAt","updatedAt") SELECT 'checkpoint_'||md5(c.id),c.id,'ทบทวน / Review: '||c.title,'สรุปสิ่งที่เรียนและรอครูตรวจคะแนน / Teacher-graded chapter review',50,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "Chapter" c WHERE NOT EXISTS(SELECT 1 FROM "Quiz" q WHERE q."chapterId"=c.id);
INSERT INTO "QuizQuestion" (id,"quizId","questionText","questionType",explanation,"orderIndex",points,"createdAt","updatedAt") SELECT 'reflection_'||md5(q.id),q.id,'สรุปแนวคิดสำคัญจากบท "'||c.title||'" อย่างน้อย 2 ประเด็น และยกตัวอย่างการนำไปใช้ 1 ตัวอย่าง / Explain two key ideas and one application example.','SHORT_ANSWER','สองแนวคิดที่ถูกต้อง 6 คะแนน และตัวอย่างการนำไปใช้ 4 คะแนน / Key ideas: 6 points; application: 4 points',0,10,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "Quiz" q JOIN "Chapter" c ON c.id=q."chapterId" WHERE q.id LIKE 'checkpoint_%' AND NOT EXISTS(SELECT 1 FROM "QuizQuestion" x WHERE x."quizId"=q.id);
